import sys

def main():
    s = sys.stdin.read().split()[0].upper()
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    print('\n'.join('%s : %d' % (c, k) for c, k in counts.items()))

main()

